function measureSelection(docu){const w=docu.width,h=docu.height,coverage=docu.selection?docu.selectionCoverage():null;let x0=0,y0=0,x1=w,y1=h;if(coverage){x0=w;y0=h;x1=-1;y1=-1;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(coverage[y*w+x]>=128){x0=Math.min(x0,x);y0=Math.min(y0,y);x1=Math.max(x1,x);y1=Math.max(y1,y);}if(x1<0)throw Error('the selection is empty');x1++;y1++;}const rw=x1-x0,rh=y1-y0;if(rw*rh>400000000)throw Error('the area is too large to measure ('+rw+'×'+rh+' px; max 400 megapixels): select a smaller region');const image=docu.composite().getContext('2d').getImageData(x0,y0,rw,rh),gray=new Float32Array(rw*rh),mask=new Uint8Array(rw*rh);for(let i=0;i<rw*rh;i++){const sx=x0+i%rw,sy=y0+(i/rw|0),o=i*4;mask[i]=coverage?coverage[sy*w+sx]>=128?1:0:1;gray[i]=.3*image.data[o]/255+.59*image.data[o+1]/255+.11*image.data[o+2]/255;}return selectionMeasured(mask,gray,rw,rh,x0,y0,grayRange(docu.depth));}
